// Brand preview mirror (Cloudflare Worker)
//
// Shows the LIVE SDR dashboard under your own brand. Every time you upload to GitHub, this updates too.
// Nothing here is in the public GitHub repo. Lock it with Cloudflare Access (your email + one-time code).
//
// Setup (Cloudflare dashboard):
//   1. Workers & Pages → Create → Worker → name it  wx-preview  → Deploy → Edit code → paste this file → Deploy
//   2. Worker → Settings → Domains & Routes → workers.dev → turn on "Cloudflare Access" (only your email)

const ORIGIN = "https://chrisjustuswx2026.github.io/nbm-ranges";
const BRAND = {
  short: "CJWX",                         // small labels ("ONLY ON CJWX")
  full: "Chris Justus Weather",     // replaces "SDR Weather Intelligence"
  desk: "CJWX Forecast Desk",            // chat replies and briefing write-ups
  team: "CJWX weather team",          // replaces "SDR Weather Intelligence (Division)" when it's doing something ("is tracking")
  ready: "",          // replaces "SDR stands ready to serve."
  dark: "#0B1A33",                       // briefing bars / bottom line
  accent: "#F5B800",                     // gold
  // the app's background colors (change these to try a look; SDR's own colors are set separately)
  theme: { bg: "#0A1428", panel: "#111E42", panel2: "#182A5C", line: "#2B3F6B" },
};
const LOGO_PNG = "";          // white logo, for dark backgrounds
const LOGO_LIGHT_PNG = "";  // dark logo, for white pages (printed briefings)

const WORDMARK = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 130"><rect width="420" height="130" rx="14" fill="${BRAND.dark}"/>
<text x="26" y="86" font-family="Arial Black,Arial,Helvetica,sans-serif" font-weight="900" font-size="78" fill="#fff" letter-spacing="2">CJWX</text>
<path d="M330 18 L296 72 L320 72 L306 114 L352 54 L326 54 L342 18 Z" fill="${BRAND.accent}"/>
<text x="28" y="116" font-family="Arial,Helvetica,sans-serif" font-weight="700" font-size="17" fill="#C9D3E3" letter-spacing="5">CHRIS JUSTUS WEATHER</text></svg>`;
const ICON_512 = "";
const ICON_180 = "";
const APP_NAME = "CJWX";                 // name under the icon on your phone
const LOGO_URL = LOGO_PNG ? "data:image/png;base64," + LOGO_PNG : "data:image/svg+xml;base64," + btoa(WORDMARK);

function swapText(t, self) {
  return t
    .replace(/(\b[Tt]he )?SDR Weather Intelligence(?: Division)? (is|will|has|stands|continues|monitors|tracks)\b/g, (m, the, v) => (the === "the " ? "the " : "The ") + BRAND.team + " " + v)
    .split("SDR WEATHER INTELLIGENCE DIVISION").join(BRAND.full.toUpperCase())
    .split("SDR WEATHER INTELLIGENCE").join(BRAND.full.toUpperCase())
    .split("SDR Weather Intelligence Division").join(BRAND.full)
    .split("SDR Weather Intelligence").join(BRAND.full)
    .split("SDR Forecast Desk").join(BRAND.desk)
    .split("SDR stands ready to serve.").join(BRAND.ready)
    .split("ONLY ON SDR").join("ONLY ON " + BRAND.short)
    .split("SDR<br>BRIEFING").join(BRAND.short + "<br>BRIEFING")
    .split("SDR BRIEFING").join(BRAND.short + " BRIEFING")
    .split("SDR Briefing").join(BRAND.short + " Briefing")
    .split("Notifications → SDR").join("Notifications → " + BRAND.short)
    .split(ORIGIN).join(self);
}

const CSS = `<style id="brand-mirror">
:root{--bg:${BRAND.theme.bg}!important;--panel:${BRAND.theme.panel}!important;--panel2:${BRAND.theme.panel2}!important;--line:${BRAND.theme.line}!important}
.brand.logo{background:transparent!important;padding:0!important}.logo{background:transparent!important;padding:0!important}.logo img{height:30px!important}
.tvc img,.rbrand img,.rplq img,.tvtop img{background:transparent!important;padding:0!important;border-radius:0!important}.tvtop img{background:rgba(10,20,40,.85)!important;padding:5px 9px!important}
.bsheet .bshd img{content:url(data:image/png;base64,${LOGO_LIGHT_PNG})}
.bsheet .bshd img{width:auto!important;height:46px!important;max-width:200px}.bsheet .bshd.sm img{height:34px!important}
@media(max-width:520px){.bsheet .bshd img{height:38px!important}}
.bsbar.g,.bsbl,.bsiss,.bsrule{background:${BRAND.dark}!important}.bsft{background:#07122a!important}
.bsht h2,.bsht small,.bssec small,.bsbox,.bspart{color:${BRAND.dark}!important}.bsbox,.bspart{border-color:${BRAND.dark}!important}
</style>`;

export default {
  async fetch(request) {
    const url = new URL(request.url), self = url.origin;
    if (url.pathname === "/" || url.pathname === "") return Response.redirect(self + "/greenville/", 302);
    // your app icon and app name for "Add to Home Screen"
    const ico = url.pathname.match(/\/icons\/(?:icon-(\d+)|badge-\d+)\.png$/);
    if (ico) { const b = (ico[1] && +ico[1] < 300) ? ICON_180 : ICON_512; return new Response(Uint8Array.from(atob(b), c => c.charCodeAt(0)), { headers: { "Content-Type": "image/png", "Cache-Control": "no-store" } }); }
    if (/manifest\.webmanifest$/.test(url.pathname)) {
      const up0 = await fetch(ORIGIN + url.pathname); let m = {}; try { m = await up0.json(); } catch (e) {}
      m.name = BRAND.full; m.short_name = APP_NAME;
      return new Response(JSON.stringify(m), { headers: { "Content-Type": "application/manifest+json", "Cache-Control": "no-store" } });
    }
    const up = await fetch(ORIGIN + url.pathname + url.search, { headers: { "User-Agent": "brand-preview" }, cf: { cacheTtl: 30 } });
    const type = up.headers.get("content-type") || "";
    const h = new Headers(up.headers); h.set("Cache-Control", "no-store"); h.set("X-Robots-Tag", "noindex, nofollow"); h.delete("content-length");
    if (/text\/html/.test(type)) {
      let t = await up.text();
      t = t.replace(/<img alt="SDR Weather Intelligence" src="data:image\/[^"]+"/g, `<img alt="SDR Weather Intelligence" src="${LOGO_URL}"`);
      t = t.replace(/getElementById\("logo"\)\.src="data:image\/[^"]+"/g, `getElementById("logo").src="${LOGO_URL}"`);
      t = swapText(t, self);
      t = t.replace(/<title>[^<]*<\/title>/, m => m.replace(/SDR[^<·|-]*/g, BRAND.full + " "));
      t = t.replace(/<meta name="apple-mobile-web-app-title" content="[^"]*">/, `<meta name="apple-mobile-web-app-title" content="${APP_NAME}">`);
      t = t.replace(/href="\.\/icons\/icon-180\.png"/, 'href="./icons/icon-180.png?b=cjwx"');
      t = t.includes("</head>") ? t.replace("</head>", CSS + "</head>") : t.replace("<style>", CSS + "<style>");
      return new Response(t, { status: up.status, headers: h });
    }
    if (/json|javascript|manifest/.test(type) || /\.(json|webmanifest)$/.test(url.pathname)) {
      const t = await up.text();
      return new Response(/channel\.json$/.test(url.pathname) ? t : swapText(t, self), { status: up.status, headers: h });
    }
    return new Response(up.body, { status: up.status, headers: h });
  },
};
